def find_period_row_fixed(row):
    """Find period and fill 6s - returns None if can't fill all 6s"""
    n = len(row)

    for p in range(1, n):
        base = [None] * p
        conflict = False

        # Build base from non-6 values
        for i in range(n):
            if row[i] != 6:
                pp = i % p
                if base[pp] is None:
                    base[pp] = row[i]
                elif base[pp] != row[i]:
                    conflict = True
                    break

        if conflict:
            continue

        # Fill output - if any 6 remains, this period is invalid
        filled = list(row)
        remaining_6s = 0
        for i in range(n):
            if row[i] == 6:
                remaining_6s += 1
                pp = i % p
                if base[pp] is None:
                    remaining_6s -= 1  # This one won't be filled
                else:
                    filled[i] = base[pp]

        # If no 6s remain, return success
        if remaining_6s == 0:
            return filled, p

    return None, None

def solve_row_combined(row):
    """Try period detection first, then nearest-neighbor fallback"""
    filled, p = find_period_row_fixed(row)

    if filled is not None:
        return filled, p

    # Period failed, try nearest-neighbor
    return solve_nearest_neighbor(row), "nn"

def solve_nearest_neighbor(row):
    filled = list(row)
    n = len(filled)
    for i in range(n):
        if filled[i] == 6:
            left_val = filled[i - 1] if i > 0 else None
            right_val = filled[i + 1] if i < n - 1 else None
            if left_val is not None:
                filled[i] = left_val
            elif right_val is not None:
                filled[i] = right_val
    return filled

